-- ===== Teams =====
on conflict (code) do update set
  name = excluded.name,
  flag = excluded.flag,
  tier = excluded.tier,
  price = excluded.price,
  group_letter = excluded.group_letter,
  confederation = excluded.confederation,
  fifa_rank = excluded.fifa_rank;

-- ===== team_advancement (defaults) =====
select id, 'none' from public.teams
on conflict (team_id) do nothing;

-- ===== Group matches (72) =====
delete from public.matches where stage = 'group' and status = 'scheduled' and home_score is null;


-- ===== Knockout placeholders (32) =====
delete from public.matches where stage <> 'group' and status = 'scheduled' and home_team_id is null and away_team_id is null;

